INSERT INTO municipalities (id, code, slug, name_en, name_ar, alt_en, blurb_en, blurb_ar, sort_order) VALUES
  (1, 'QADA', 'ad-dawhah', 'Ad Dawhah', 'الدوحة', 'Doha', 'The capital. Where the country works, eats and argues about traffic.', 'العاصمة. حيث يعمل البلد ويأكل ويتحدث عن الزحام.', 10),
  (2, 'QAZA', 'al-daayen', 'Al Daayen', 'الضعاين', '', 'Lusail, the new city on the coast, plus a lot of open ground behind it.', 'لوسيل، المدينة الجديدة على الساحل، ومساحات مفتوحة خلفها.', 20),
  (3, 'QAKH', 'al-khor', 'Al Khor', 'الخور', 'Al Khor and Al Thakhira', 'Mangroves, flamingos and the road north to the gas coast.', 'أشجار المانغروف وطيور الفلامنغو والطريق شمالاً إلى ساحل الغاز.', 30),
  (4, 'QASH', 'al-shahaniya', 'Al Shahaniya', 'الشحانية', '', 'The big empty middle — camel tracks, film-set forts and the Dukhan road.', 'الوسط الفارغ الواسع — آثار الجمال وقلاع التصوير وطريق دخان.', 40),
  (5, 'QARA', 'ar-rayyan', 'Ar Rayyan', 'الريان', 'Al Rayyan', 'By far the largest municipality. Football, universities and a lot of desert.', 'أكبر بلدية بفارق كبير. كرة القدم والجامعات والكثير من الصحراء.', 50),
  (6, 'QAUS', 'umm-salal', 'Umm Salal', 'أم صلال', 'Umm Slal', 'The small one in the middle that everyone drives through and nobody stops in.', 'البلدية الصغيرة في الوسط التي يمر بها الجميع ولا يتوقف فيها أحد.', 60),
  (7, 'QAWA', 'al-wakrah', 'Al Wakrah', 'الوكرة', 'Al Wakra', 'Old fishing town, new metro line, and the dunes at Sealine at the end of it.', 'بلدة صيد قديمة وخط مترو جديد وكثبان سيلين في نهايته.', 70),
  (8, 'QAMS', 'al-shamal', 'Al Shamal', 'الشمال', 'Madinat ash Shamal', 'The thin northern tip. Bahrain is a short swim away and it feels like it.', 'الطرف الشمالي الضيق. البحرين قريبة جداً ويبدو الأمر كذلك.', 80);
